/** Real dispatcher admission versus independently emitted, homogeneously clipped payload triangles. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeGearCullingChecks {
 private static int stage,ticks,frames,draws,visibleFrames,missingFrames,checks;private static boolean complete;private static int lastDraws;
 private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native culling client stage="+stage+" tick="+ticks+": "+why);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT) public static final class Renderers {@SubscribeEvent(priority=EventPriority.LOWEST) public static void register(EntityRenderersEvent.RegisterRenderers e){if(NativeGearCullingFixture.enabled())e.registerBlockEntityRenderer(NativeGearBindings.ENTITY,context->new BlockEntityRenderer<NativeGearEntity>(){private final NativeGearRenderer delegate=new NativeGearRenderer(context);public void render(NativeGearEntity owner,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){if(owner.getBlockPos().equals(NativeGearCullingFixture.ROOT)&&NativeGearRenderer.visible(owner))draws++;delegate.render(owner,partial,poses,buffers,light,overlay);}public AABB getRenderBoundingBox(NativeGearEntity owner){return delegate.getRenderBoundingBox(owner);}public int getViewDistance(){return delegate.getViewDistance();}});}}
 private static final class Records implements VertexConsumer {java.util.ArrayList<Vector4f> vertices=new java.util.ArrayList<>();public VertexConsumer addVertex(float x,float y,float z){vertices.add(new Vector4f(x,y,z,1));return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static float distance(Vector4f p,int plane){return switch(plane){case 0->p.w+p.x;case 1->p.w-p.x;case 2->p.w+p.y;case 3->p.w-p.y;case 4->p.w+p.z;default->p.w-p.z;};}
 private static boolean clipped(Vector4f a,Vector4f b,Vector4f c){java.util.List<Vector4f> points=java.util.List.of(a,b,c);for(int plane=0;plane<6;plane++){var next=new java.util.ArrayList<Vector4f>();for(int n=0;n<points.size();n++){var p=points.get(n);var q=points.get((n+1)%points.size());float dp=distance(p,plane),dq=distance(q,plane);if(dp>=0)next.add(p);if((dp>=0)!=(dq>=0))next.add(new Vector4f(p).lerp(q,dp/(dp-dq)));}points=next;if(points.isEmpty())return false;}return points.size()>=3;}
 @SubscribeEvent public static void frame(RenderLevelStageEvent e){if(!NativeGearCullingFixture.enabled()||e.getStage()!=RenderLevelStageEvent.Stage.AFTER_LEVEL)return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.getOverlay()!=null||mc.screen!=null)return;var root=NativeGearFormation.at(mc.level,NativeGearCullingFixture.ROOT);if(root==null||root.payloadView()==null||root.payloadView().cells().size()!=9)return;double expectedY=stage==0?115:110;if(Math.abs(mc.player.getY()-expectedY)>.01||mc.gameMode.getPlayerMode()!=GameType.SURVIVAL||mc.player.getInventory().selected!=0||!mc.player.getMainHandItem().isEmpty())return;
 var records=new Records();NativeGearPayloadRenderer.draw(root,NativeGearVisualClock.pose(root),0,new PoseStack(),type->records,0xf000f0,0);var camera=e.getCamera().getPosition();var matrix=new Matrix4f(e.getProjectionMatrix()).mul(e.getModelViewMatrix());var p=root.getBlockPos();for(var v:records.vertices){v.add((float)(p.getX()-camera.x),(float)(p.getY()-camera.y),(float)(p.getZ()-camera.z),0);matrix.transform(v);}int triangles=0;for(int n=0;n+3<records.vertices.size();n+=4){if(clipped(records.vertices.get(n),records.vertices.get(n+1),records.vertices.get(n+2)))triangles++;if(clipped(records.vertices.get(n),records.vertices.get(n+2),records.vertices.get(n+3)))triangles++;}int actual=draws-lastDraws;lastDraws=draws;if(++frames<=30)return;need(triangles>0,"actual payload vertices must clip inside main viewport, vertices="+records.vertices.size());visibleFrames++;if(actual==0)missingFrames++;need(actual<=1,"single renderer per main frame actual="+actual);if(visibleFrames==20){System.out.println("[vandorlabs][gear-culling] sample stage="+stage+" actualDraws="+actual+" clippedTriangles="+triangles+" missing="+missingFrames+" rootSectionY=112..128 camera="+camera);try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){var path=mc.gameDirectory.toPath().resolve("screenshots/native-arm-culling-"+stage+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);}catch(java.io.IOException ex){throw new RuntimeException(ex);}need(missingFrames==0,"visible ordinary payload lost with origin section behind camera; missingFrames="+missingFrames+" triangles="+triangles);if(stage==0){stage=1;frames=visibleFrames=missingFrames=0;PacketDistributor.sendToServer(new NativeGearCullingFixture.Mode(0));}else{complete=true;PacketDistributor.sendToServer(new NativeGearCullingFixture.Mode(1));}}}
 @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!NativeGearCullingFixture.enabled())return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}if(complete){System.out.println("[vandorlabs][gear-culling] client PASS checks="+checks+" actualDispatcher/twoCameras/nineOrdinaryCells/clippedTriangles/oneOwner");mc.level.disconnect();mc.disconnect();mc.stop();complete=false;return;}if(mc.level==null||mc.player==null)return;mc.options.hideGui=true;mc.getToasts().clear();need(++ticks<800,"bounded stage="+stage+" mode="+mc.gameMode.getPlayerMode()+" slot="+mc.player.getInventory().selected+" held="+mc.player.getMainHandItem()+" position="+mc.player.position());}
}
